import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"CephFS as a Scalable Filer - Rafael Lopez & Brett Milford, Monash University","description":"","frontmatter":{"title":"CephFS as a Scalable Filer - Rafael Lopez & Brett Milford, Monash University","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["CephFS","分布式文件系统","莫纳什大学","性能测试","存储解决方案"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/CephFS_as_a_Scalable_Filer_-_Rafael_Lopez_Brett_Milford_Monash_University.md","filePath":"posts/2019/CephFS_as_a_Scalable_Filer_-_Rafael_Lopez_Brett_Milford_Monash_University.md","lastUpdated":1780459816000}'),s={name:"posts/2019/CephFS_as_a_Scalable_Filer_-_Rafael_Lopez_Brett_Milford_Monash_University.md"};function l(p,e,_,n,i,C){return a(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p>莫纳什大学的研究人员和工程师Rafael Lopez和Brett Milford在会议上分享了他们在Ceph文件系统（CFS）方面的应用与实践。以下是对会议内容的总结：</p><p><strong>莫纳什大学简介</strong></p><p>莫纳什大学是澳大利亚的一所大型研究型大学，拥有超过70,000名学生和44,000名研究生。学校的研究数据中心提供高性能计算和可扩展存储服务，支持医学、药学、信息技术和商业等多个领域的研究。</p><p><strong>Ceph文件系统（CFS）在莫纳什大学的应用</strong></p><p>莫纳什大学在CFS方面的应用主要集中在以下几个方面：</p><ul><li><strong>CFS集群</strong>： 学校拥有多个CFS集群，用于存储和共享数据。</li><li><strong>虚拟文件服务器</strong>： 使用CFS和RBD构建虚拟文件服务器，提供NFS和SMB服务。</li><li><strong>对象存储</strong>： 利用CFS对象存储服务，存储大量数据。</li></ul><p><strong>CFS性能测试</strong></p><p>Rafael对CFS在不同场景下的性能进行了测试，并与虚拟文件服务器进行了比较。主要测试结果显示，CFS在NFS和SMB性能方面优于虚拟文件服务器，特别是在读写带宽和IOPS方面。对于元数据密集型任务，如文件复制和目录遍历，CFS的性能也明显优于虚拟文件服务器。</p><p><strong>CFS在莫纳什大学的挑战</strong></p><ul><li><strong>Ceph版本</strong>： 莫纳什大学使用的是Red Hat Enterprise Ceph，存在一些包装问题。</li><li><strong>Ceph访问</strong>： 提供原生Ceph访问和强制配额存在一些挑战。</li><li><strong>备份</strong>： 备份大型文件系统存在一些挑战。</li></ul><p><strong>后续行动计划</strong></p><ul><li><strong>升级Ceph版本</strong>： 考虑升级Ceph版本，以解决包装问题。</li><li><strong>优化Ceph配置</strong>： 优化Ceph配置，以提高性能和可靠性。</li><li><strong>测试Ceph功能</strong>： 测试Ceph的新功能，以进一步提高其可用性和可靠性。</li></ul><p><strong>会议总结</strong></p><p>莫纳什大学在Ceph文件系统方面取得了显著成果，并成功将其应用于研究数据存储和共享。CFS在莫纳什大学的性能表现良好，但还存在一些挑战需要解决。莫纳什大学将继续优化Ceph配置，并探索新的技术，以进一步提高Ceph的性能和可靠性。</p>',15)])])}const g=t(s,[["render",l]]);export{h as __pageData,g as default};
